import {registerCardComponent} from "@pihanga2/core";
import {SUSPENSE_CARD} from "./suspense.types";
import {SuspenseComponent} from "./suspense.component";

export * from "./suspense.types";

// No events — structural card.
registerCardComponent({
  name: SUSPENSE_CARD,
  component: SuspenseComponent,
});

import * as React from "react";
import {Suspense} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import type {SuspenseProps} from "./suspense.types";

// ── Preset maps (mirrors loading-skeleton) ─────────────────────────────────────

const ROW_SIZE_CLASS: Record<string, string> = {
  xs: "h-3",
  sm: "h-5",
  md: "h-10",
  lg: "h-14",
  xl: "h-20",
};

const SPACING_CLASS: Record<string, string> = {
  sm: "gap-2",
  md: "gap-3",
  lg: "gap-4",
};

// ── Inline skeleton (used when no `fallback` card is provided) ─────────────────

function InlineSkeleton({
  rows = 3,
  rowSize = "md",
  spacing = "md",
  rowClassName,
  className,
}: Pick<
  SuspenseProps,
  "rows" | "rowSize" | "spacing" | "rowClassName" | "className"
>) {
  const rowCls =
    rowClassName ??
    `rounded-md bg-foreground/15 ${ROW_SIZE_CLASS[rowSize ?? "md"]}`;
  const wrapperCls =
    className ?? `flex w-full flex-col ${SPACING_CLASS[spacing ?? "md"]}`;

  return (
    <div className={wrapperCls}>
      {Array.from({length: rows}).map((_, i) => (
        <div key={i} className={`animate-pulse ${rowCls}`} />
      ))}
    </div>
  );
}

// ── Component ──────────────────────────────────────────────────────────────────

/**
 * SuspenseComponent
 *
 * Wraps `content` in a React `<Suspense>` boundary so it commits and paints
 * independently of the rest of the tree.
 *
 * When `content`'s registered component is code-split with `React.lazy`, this
 * boundary catches the thrown promise and shows either:
 *   • a custom `fallback` card (when the `fallback` prop is set), or
 *   • an animated shimmer skeleton (default).
 */
export const SuspenseComponent = (
  props: PiCardProps<SuspenseProps>,
): React.ReactNode => {
  const {
    cardName,
    content,
    fallback,
    rows,
    rowSize,
    spacing,
    rowClassName,
    className,
  } = props;

  const fallbackNode = fallback ? (
    <Card cardName={fallback} parentCard={cardName} />
  ) : (
    <InlineSkeleton
      rows={rows}
      rowSize={rowSize}
      spacing={spacing}
      rowClassName={rowClassName}
      className={className}
    />
  );

  return (
    <Suspense fallback={fallbackNode}>
      <Card cardName={content} parentCard={cardName} />
    </Suspense>
  );
};

import {createCardDeclaration} from "@pihanga2/core";
import type {PiCardRef} from "@pihanga2/core";
import type {SkeletonRowSize, SkeletonSpacing} from "@/cards/loadingSkeleton";

// ── Card id ───────────────────────────────────────────────────────────────────

export const SUSPENSE_CARD = "shad/suspense";

// ── Card declaration factory ──────────────────────────────────────────────────

export const Suspense = createCardDeclaration<SuspenseProps>(SUSPENSE_CARD);

// ── Props ─────────────────────────────────────────────────────────────────────

/**
 * Props for the `shad/suspense` card.
 *
 * Wraps `content` in a React `<Suspense>` boundary so it can suspend
 * independently of its siblings (e.g. when its component is code-split via
 * `React.lazy`).
 *
 * **Default fallback** — animated shimmer skeleton rows (same as
 * `shad/loading-skeleton`); customise with `rows` / `rowSize` / `spacing`:
 * ```ts
 * registerCard("myApp/editorSection", PiSuspense({
 *   content: "myApp/codeEditor",
 *   rows:    5,
 *   rowSize: "lg",
 * }));
 * ```
 *
 * **Custom fallback card** — pass any registered card name via `fallback` to
 * replace the built-in skeleton entirely:
 * ```ts
 * registerCard("myApp/graphSection", PiSuspense({
 *   content:  "myApp/graphView",
 *   fallback: "myApp/graphPlaceholder",
 * }));
 * ```
 */
export type SuspenseProps = {
  /**
   * The card to render inside the Suspense boundary.
   * Typically registered with a `React.lazy` component so it can suspend.
   */
  content: PiCardRef;

  /**
   * Optional card to use as the Suspense fallback.
   * When provided, the built-in skeleton props below are ignored.
   */
  fallback?: PiCardRef;

  // ── Built-in skeleton fallback options (ignored when `fallback` is set) ────

  /**
   * Number of placeholder rows shown while suspended.
   * @default 3
   */
  rows?: number;

  /**
   * Named height preset for each shimmer row.
   * @default "md"
   */
  rowSize?: SkeletonRowSize;

  /**
   * Named gap preset between shimmer rows.
   * @default "md"
   */
  spacing?: SkeletonSpacing;

  /**
   * Raw Tailwind classes for every shimmer row.
   * When set, takes precedence over `rowSize`.
   */
  rowClassName?: string;

  /**
   * Raw Tailwind classes for the outer wrapper `<div>`.
   * When set, takes precedence over `spacing`.
   */
  className?: string;
};
// No events — display-only structural card.

Wraps a card in a React `<Suspense>` boundary so it can suspend and paint
independently of its siblings — useful for code-split cards registered with
`React.lazy`.

| Prop | Default | Purpose |
|---|---|---|
| `content` | — | Card to render inside the Suspense boundary |
| `fallback` | — | Card to show while suspended (overrides the built-in skeleton) |
| `rows` | `3` | Skeleton row count (ignored when `fallback` card is set) |
| `rowSize` | `"md"` | Row height preset: `"xs"` `"sm"` `"md"` `"lg"` `"xl"` |
| `spacing` | `"md"` | Gap between rows: `"sm"` `"md"` `"lg"` |
| `rowClassName` | — | Raw Tailwind override for rows (takes precedence over `rowSize`) |
| `className` | — | Raw Tailwind override for wrapper (takes precedence over `spacing`) |

## Lazy-register a heavy card component

```ts
// myHeavyCard/index.ts
import React from "react";
import {registerCardComponent} from "@pihanga2/core";
import {MY_HEAVY_CARD} from "./myHeavyCard.types";

const MyHeavyComponent = React.lazy(() =>
  import("./myHeavyCard.component").then(m => ({default: m.MyHeavyComponent}))
);

registerCardComponent({ name: MY_HEAVY_CARD, component: MyHeavyComponent });
```

## Wrap it with the suspense card

```ts
import {registerCard} from "@pihanga2/core";
import {PiSuspense} from "@/cards/suspense";

// Default built-in skeleton fallback:
registerCard("myApp/editorSection", PiSuspense({
  content: "myApp/codeEditor",
  rows:    5,
  rowSize: "lg",
}));

// Custom fallback card:
registerCard("myApp/graphSection", PiSuspense({
  content:  "myApp/graphView",
  fallback: "myApp/graphPlaceholder",
}));
```
